package com.postech.auth.token;
import static org.assertj.core.api.Assertions.*; import io.jsonwebtoken.Jwts; import org.junit.jupiter.api.Test; import java.nio.charset.StandardCharsets; import java.util.*;
class EmissorJwtTest { private static final String SECRET="01234567890123456789012345678901"; @Test void emiteContrato(){String t=new EmissorJwt(SECRET).emitir("u-1","mateus",List.of("CLIENTE")); var c=Jwts.parser().verifyWith(io.jsonwebtoken.security.Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8))).requireIssuer("workshop-auth").requireAudience("workshop-service").build().parseSignedClaims(t).getPayload(); assertThat(c.getId()).isNotBlank(); assertThat(c.getSubject()).isEqualTo("u-1"); assertThat(c.get("roles",List.class)).containsExactly("CLIENTE"); assertThat(c.getExpiration()).isAfter(new Date()); } @Test void rejeitaSegredoCurto(){assertThatThrownBy(()->new EmissorJwt("curto")).isInstanceOf(IllegalArgumentException.class);} }
